refentry.refsect1:
  &reftitle.examples;



    clearstatcache example


<?php

$file = tempnam(sys_get_temp_dir(), 'stat-demo-');
file_put_contents($file, 'Hello');

echo "Run this command in another shell:\n";
echo "\techo \" World!\" >> $file\n";

$before = filesize($file); // caches the metadata

sleep(20); // Run the echo-command in another shell

$cached = filesize($file); // stale data is returned

clearstatcache();

$fresh = filesize($file);  // returns the correct data

printf("Before: %d\nCached: %d\nFresh: %d\n", $before, $cached, $fresh);

unlink($file);


    &example.outputs.similar;


Run this command in another shell:
    echo " World!" >> /tmp/stat-demo-6fjvs4vir9ll2haCl4W
Before: 5
Cached: 5
Fresh: 13
